package fable.hideseek.imba.net;import fable.hideseek.imba.config.MessageSettingsConfig;import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;import net.minecraft.network.PacketByteBuf;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.Identifier;public final class MessageSettingsNetworking{public static final Identifier REQUEST=new Identifier("imba","message_settings_request"),SET=new Identifier("imba","message_settings_set"),SYNC=new Identifier("imba","message_settings_sync");private MessageSettingsNetworking(){}public static void register(){ServerPlayNetworking.registerGlobalReceiver(REQUEST,(server,player,handler,buf,sender)->server.execute(()->{if(player.hasPermissionLevel(2))sendSync(player);}));ServerPlayNetworking.registerGlobalReceiver(SET,(server,player,handler,buf,sender)->{String key=buf.readString(128);boolean enabled=buf.readBoolean();server.execute(()->{if(!player.hasPermissionLevel(2))return;MessageSettingsConfig.setEnabled(key,enabled);sendSync(player);});});}public static void sendSync(ServerPlayerEntity player){PacketByteBuf out=PacketByteBufs.create();var state=MessageSettingsConfig.snapshot();out.writeVarInt(MessageSettingsConfig.CATALOG.size());for(var entry:MessageSettingsConfig.CATALOG){out.writeString(entry.key(),128);out.writeBoolean(state.getOrDefault(entry.key(),entry.defaultEnabled()));}ServerPlayNetworking.send(player,SYNC,out);}}
